    public static boolean turn(LocalPlayer p,double dx,double dy){if(!active())return false;if(ready()){if(GroundCameraAim.universe(flight))spaceAim=OrbitAttitude.turn(spaceAim,dx*.15,dy*.15);else{attitude=GroundCosmos.turn(state,attitude,dx*.15,dy*.15);spaceAim=GroundTransit.inputOrientation(ephemeris,planet,state,attitude,flight.tick());}}return true;}
