/** Accepted low net/planar chart plus a separate orbital display stage.
 * Both stages consume the SAME cached GroundCover faces, never another world/ledger. */
public final class GroundRenderer {
    private record Buffer(long stamp,VertexBuffer gpu){}
    private record Request(int tile,double distance){}
    private static final Map<Integer,Buffer> BUFFERS=new LinkedHashMap<>(16,.75f,true);
    private static final Buffer[][] PLANETS=new Buffer[GroundCosmos.COUNT][6];
    private static Buffer[] COVER=PLANETS[0];private static int activePlanet=-1;
    private static ShaderInstance shader,orbitShader;private static GroundMaterialAtlas materials;private static int detailMask;
    private static int pending,drawn;private static boolean transparentPass;
    public static void clear(){GroundTextureFilter.reset();GroundStars.clear();GroundSunRenderer.clear();for(var b:BUFFERS.values())close(b);BUFFERS.clear();for(var planet:PLANETS){for(var b:planet)close(b);Arrays.fill(planet,null);}activePlanet=-1;if(materials!=null)materials.close();materials=null;if(detailMask!=0)GL11.glDeleteTextures(detailMask);detailMask=0;pending=drawn=0;}
    private static void close(Buffer b){if(b!=null&&b.gpu!=null)b.gpu.close();}
    public static boolean loaded(Cell c){if(c==null||GroundClient.world()==null||(!GroundSpace.stored(c)&&!GroundSpace.mask(GroundClient.world().config(),c)))return false;var b=BUFFERS.get(GroundSpace.tile(c));return b!=null&&b.stamp==GroundClient.world().stamp(GroundSpace.tile(c));}
    public static String status(){return shader==null?"远缝Shader未就绪":GroundClient.ready()&&GroundClient.eye().y()>GroundOrbit.START?(orbitShader==null?"太空Shader未就绪":"整星缓存 "+drawn+"/6 · 相机移动不烘焙") :"平面网格"+drawn+" / 待建"+pending+" · 缓存展开地表";}
    public static void initialize(){
        CoreShaderRegistrationCallback.EVENT.register(c->c.register(ResourceLocation.parse("starfold:ground_gap"),DefaultVertexFormat.POSITION_TEX_COLOR,s->{shader=s;clear();}));
        CoreShaderRegistrationCallback.EVENT.register(c->c.register(ResourceLocation.parse("starfold:ground_orbit"),DefaultVertexFormat.POSITION_TEX_COLOR,s->{orbitShader=s;clear();}));
        GroundSky.initialize();GroundStars.initialize();GroundSunRenderer.initialize();
        DimensionRenderingRegistry.registerCloudRenderer(GroundServer.DIMENSION,c->{});DimensionRenderingRegistry.registerWeatherRenderer(GroundServer.DIMENSION,c->{});
        ResourceManagerHelper.get(PackType.CLIENT_RESOURCES).registerReloadListener(new SimpleSynchronousResourceReloadListener(){@Override public ResourceLocation getFabricId(){return ResourceLocation.parse("starfold:ground_gap_meshes");}@Override public void onResourceManagerReload(ResourceManager r){clear();}});
        net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientLifecycleEvents.CLIENT_STOPPING.register(c->clear());
