package dev.starfold;

import dev.starfold.CubeSurfaceTopology.*;
import dev.starfold.PlanetSpace.Side;
import java.util.*;

/** Sparse canonical state. The permanent physical core is a reversible overlay, not a camera mask. */
public final class GroundWorld {
    public static final int MAX_EDITS=32768;
    private final Map<Integer,Integer> edits=new HashMap<>();
    private final Map<Integer,Map<Integer,Integer>> affected=new HashMap<>();
    private final Map<Integer,Long> stamps=new HashMap<>();
    private final long[] faceStamps=new long[6];
    public long faceStamp(Face face){return Math.max(generation,faceStamps[face.ordinal()]);}
    private record Mesh(long stamp,List<GroundMesh.Quad> faces){}
    private final LinkedHashMap<Integer,Mesh> meshes=new LinkedHashMap<>(16,.75f,true);
    public List<GroundMesh.Quad> mesh(int tile){var m=meshes.get(tile);if(m==null||m.stamp!=stamp(tile)){m=new Mesh(stamp(tile),List.copyOf(GroundMesh.build(this,tile)));meshes.put(tile,m);while(meshes.size()>256)meshes.remove(meshes.keySet().iterator().next());}return m.faces;}
    private long revision,generation;
    private GroundSpace.Config config;
    public final int planet;
    public int base(Cell p){int m=initial(p);return planet==1&&m==22?38:planet==1&&m==21?36:m;}
    public GroundWorld(GroundSpace.Config c){this(c,1,new int[0]);}
    public GroundWorld(GroundSpace.Config c,long rev,int[] pairs){this(0,c,rev,pairs);}
    public GroundWorld(int planet,GroundSpace.Config c,long rev,int[] pairs){
        this.planet=GroundCosmos.valid(planet);
        if(c==null||rev<1||pairs==null||pairs.length%2!=0||pairs.length>MAX_EDITS*2)throw new IllegalArgumentException("Snapshot");config=c;revision=rev;generation=rev;
        for(int i=0;i<pairs.length;i+=2){var p=GroundSpace.cell(pairs[i]);int m=pairs[i+1];if(p.h()==GroundSpace.MIN||!GroundMaterials.valid(m)||m==base(p)||edits.putIfAbsent(pairs[i],m)!=null)throw new IllegalArgumentException("Invalid sparse edit");track(p,1);}
    }
    public boolean detailed(int tile){return affected.containsKey(tile);}
    public GroundSpace.Config config(){return config;}
    public long revision(){return revision;}
    public long stamp(int tile){return Math.max(generation,stamps.getOrDefault(tile,0L));}
    public int[] snapshot(){var sorted=new TreeMap<>(edits);int[] out=new int[sorted.size()*2];int n=0;for(var e:sorted.entrySet()){out[n++]=e.getKey();out[n++]=e.getValue();}return out;}
    public static int initial(Cell p){if(!GroundSpace.stored(p))return 0;if(p.h()==GroundSpace.MIN)return 1;if(p.h()< -3)return 2;if(p.h()< -1)return 21;if(p.h()==-1)return 22;return 0;}
    public int get(Cell p){if(p==null)return 0;if(p.h()<GroundSpace.MIN)return 1;if(GroundSpace.mask(config,p))return 1;if(!GroundSpace.stored(p))return 0;return edits.getOrDefault(GroundSpace.index(p),base(p));}
    public int material(GroundChart chart,int x,int y,int z){return get(chart.owner(x,y,z));}
    public Cell neighbor(Cell p,Side side){var n=switch(side){case DOWN->p.add(0,-1,0);case UP->p.add(0,1,0);case WEST->p.add(-1,0,0);case EAST->p.add(1,0,0);case NORTH->p.add(0,0,-1);case SOUTH->p.add(0,0,1);};return GroundSpace.TOPOLOGY.canonical(n).cell();}
    public boolean editable(Cell p){return GroundSpace.stored(p)&&p.h()>GroundSpace.MIN&&!GroundSpace.mask(config,p);}
    public boolean set(Cell p,int material){if(!editable(p)||!GroundMaterials.valid(material))throw new IllegalArgumentException("Protected cell/material");int key=GroundSpace.index(p);if(get(p)==material)return false;if(material!=base(p)&&!edits.containsKey(key)&&edits.size()>=MAX_EDITS)throw new IllegalStateException("32768 edit limit");boolean had=edits.containsKey(key);bump();if(material==base(p))edits.remove(key);else edits.put(key,material);track(p,(edits.containsKey(key)?1:0)-(had?1:0));return true;}
    public boolean delta(long rev,int key,int material){if(rev!=revision+1||key<0||key>=GroundSpace.VOLUME||!GroundMaterials.valid(material))return false;var p=GroundSpace.cell(key);return editable(p)&&set(p,material)&&revision==rev;}
    public boolean resize(GroundSpace.Config next,Collection<GroundMotion.State> players){if(next.equals(config))return true;var old=config;config=next;for(var p:players)if(!GroundFlight.clear(this,p.pose())){config=old;return false;}if(revision==Long.MAX_VALUE){config=old;throw new IllegalStateException("Revision exhausted");}bump();generation=revision;return true;}
    private void bump(){if(revision==Long.MAX_VALUE)throw new IllegalStateException("Revision exhausted");revision++;}
    private void track(Cell p,int change){var cells=new ArrayList<Cell>();cells.add(p);for(var s:Side.values())cells.add(neighbor(p,s));for(var n:cells)if(GroundSpace.stored(n)){int tile=GroundSpace.tile(n),key=GroundSpace.index(n);if(change!=0){var counts=affected.computeIfAbsent(tile,k->new HashMap<>());int count=counts.getOrDefault(key,0)+change;if(count==0)counts.remove(key);else counts.put(key,count);if(counts.isEmpty())affected.remove(tile);}stamps.put(tile,revision);faceStamps[n.face().ordinal()]=revision;}}
    public Set<Integer> candidates(int tile){
        int u0=tile%GroundSpace.ACROSS*GroundSpace.TILE,v0=tile/GroundSpace.ACROSS%GroundSpace.ACROSS*GroundSpace.TILE;var face=Face.values()[tile/(GroundSpace.ACROSS*GroundSpace.ACROSS)];var out=new HashSet<Integer>();
        for(int u=u0;u<u0+GroundSpace.TILE;u++)for(int v=v0;v<v0+GroundSpace.TILE;v++){
            var c=new Cell(face,u,-1,v);out.add(GroundSpace.index(c));
            if(GroundSpace.column(config,c)){if(config.height()<=GroundSpace.MAX)out.add(GroundSpace.index(new Cell(face,u,config.height()-1,v)));boolean edge=false;for(var s:new Side[]{Side.NORTH,Side.SOUTH,Side.WEST,Side.EAST})if(!GroundSpace.column(config,neighbor(c,s)))edge=true;
                if(edge)for(int h=0;h<Math.min(config.height(),GroundSpace.MAX);h++)out.add(GroundSpace.index(new Cell(face,u,h,v)));
            }
        }
        out.addAll(affected.getOrDefault(tile,Map.of()).keySet());return out;
