package dev.starfold;

import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.*;
import net.minecraft.world.level.EmptyBlockGetter;
import net.minecraft.world.level.block.Block;
import java.util.*;

/** Ground-only open registry. Legacy material ids stay fixed; saved names prevent registry drift. */
public final class GroundMaterials {
    public static final List<String> NAMES;
    private static final Map<String,Integer> IDS=new HashMap<>();
    private static final boolean[] OPAQUE;
    static {
        var names=new ArrayList<String>();for(String n:DomeBuildPalette.NAMES)names.add("minecraft:"+n);
        BuiltInRegistries.BLOCK.keySet().stream().map(Object::toString).sorted().filter(n->!names.contains(n)).forEach(names::add);
        if(names.size()>8192)throw new IllegalStateException("Ground material encoding exhausted");
        NAMES=List.copyOf(names);OPAQUE=new boolean[names.size()];
        for(int i=0;i<names.size();i++){IDS.put(names.get(i),i);OPAQUE[i]=i!=0&&block(i).defaultBlockState().isSolidRender(EmptyBlockGetter.INSTANCE,BlockPos.ZERO);}
    }
    public static boolean valid(int id){return id>=0&&id<NAMES.size();}
    public static Block block(int id){if(!valid(id))throw new IllegalArgumentException("Material");return BuiltInRegistries.BLOCK.get(ResourceLocation.parse(NAMES.get(id)));}
    public static int id(Block b){return IDS.getOrDefault(BuiltInRegistries.BLOCK.getKey(b).toString(),-1);}
    public static int id(Item item){if(item instanceof BlockItem b)return id(b.getBlock());if(item==Items.WATER_BUCKET)return IDS.get("minecraft:water");if(item==Items.LAVA_BUCKET)return IDS.get("minecraft:lava");if(item==Items.POWDER_SNOW_BUCKET)return IDS.get("minecraft:powder_snow");return -1;}
    public static boolean opaque(int id){return valid(id)&&OPAQUE[id];}
    public static boolean faceVisible(int material,int neighbor){return neighbor==0||material!=neighbor&&!opaque(neighbor);}
    public static ListTag palette(){var list=new ListTag();for(String n:NAMES)list.add(StringTag.valueOf(n));return list;}
    public static int[] restore(CompoundTag tag,int[] pairs){
        int format=tag.getInt("format");if(format==1){for(int i=1;i<pairs.length;i+=2)if(!DomeBuildPalette.valid(pairs[i]))throw new IllegalArgumentException("Legacy material");return pairs;}
        if(format!=2||!tag.contains("materials",9))throw new IllegalArgumentException("Missing Ground registry palette");
        var palette=tag.getList("materials",8);if(palette.size()<DomeBuildPalette.NAMES.length||palette.size()>8192)throw new IllegalArgumentException("Palette size");
        var seen=new HashSet<String>();int[] mapping=new int[palette.size()];
        for(int i=0;i<mapping.length;i++){String name=palette.getString(i);if(!seen.add(name)||!IDS.containsKey(name))throw new IllegalArgumentException("Missing/duplicate block: "+name);mapping[i]=IDS.get(name);}
        for(int i=0;i<DomeBuildPalette.NAMES.length;i++)if(mapping[i]!=i)throw new IllegalArgumentException("Legacy palette reordered");
        for(int i=1;i<pairs.length;i+=2){int id=pairs[i];if(id<0||id>=mapping.length)throw new IllegalArgumentException("Saved material");pairs[i]=mapping[id];}return pairs;
    }
    public static void verifyWire(ListTag palette){if(!palette.equals(palette()))throw new IllegalArgumentException("Ground block registries differ; use matching mods");}
    public static int packedSide(int material,int side){if(!valid(material)||side<0||side>5)throw new IllegalArgumentException("Packed material");return side+8*(material>>>8);}
    private GroundMaterials(){}
}

