package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import org.joml.Quaterniond;

/** Explicit reference ownership. Space position/velocity are authoritative universe vectors;
 * local position/velocity are planet-frame vectors. Conversions never cancel momentum. */
public final class GroundTransit {
    public static final double ENTER=3072,EXIT=4096,ACCEL=4,SPACE_RADIUS=24576;
    public record State(long tick,boolean space,int planet,Point position,Point velocity,Quaterniond orientation,GroundMotion.State local,boolean braking,GroundGuidance.Options guidance){
        public State(long tick,boolean space,int planet,Point position,Point velocity,Quaterniond orientation,GroundMotion.State local,boolean braking){this(tick,space,planet,position,velocity,orientation,local,braking,GroundGuidance.Options.OFF);}
        public State{if(guidance==null||braking&&guidance.relativeBrake())throw new IllegalArgumentException("Conflicting brake modes");GroundEphemeris.time(tick);GroundCosmos.valid(planet);GroundEphemeris.point(position);GroundEphemeris.point(velocity);GroundEphemeris.quaternion(orientation);if(position.length()>200000||velocity.length()>256||space&&local!=null||!space&&local==null)throw new IllegalArgumentException("Transit state");if(!space&&(GroundOrbit.position(local.pose()).sub(position).length()>1e-6||Math.abs(localOrientation(local).dot(orientation))<1-1e-8))throw new IllegalArgumentException("Inconsistent local state");orientation=new Quaterniond(orientation);}
        @Override public Quaterniond orientation(){return new Quaterniond(orientation);}
    }
    public static State guidance(State s,GroundGuidance.Options options){return new State(s.tick,s.space,s.planet,s.position,s.velocity,s.orientation,s.local,options.relativeBrake()?false:s.braking,options);}
    private static Quaterniond localOrientation(GroundMotion.State s){return GroundOrbit.frame(s.pose()).rotation().mul(s.orientation()).normalize();}
    public static State local(long tick,int id,GroundMotion.State s,Point relativeVelocity){return new State(tick,false,id,GroundOrbit.position(s.pose()),relativeVelocity,localOrientation(s),s,false);}
    public static State space(long tick,int reference,Point p,Point v,Quaterniond q,boolean braking){return new State(tick,true,reference,p,v,q,null,braking);}
    public static Point position(GroundEphemeris.Model m,State s,double t){return s.space?s.position:m.at(s.planet,t).world(s.position);}
    public static Point velocity(GroundEphemeris.Model m,State s,double t){return s.space?s.velocity:m.at(s.planet,t).worldVelocity(s.position,s.velocity);}
    public static Quaterniond orientation(GroundEphemeris.Model m,State s,double t){return s.space?s.orientation():m.at(s.planet,t).rotation().mul(s.orientation()).normalize();}
    public static State detach(GroundEphemeris.Model m,State s){if(s.space)return s;return guidance(space(s.tick,s.planet,position(m,s,s.tick),velocity(m,s,s.tick),orientation(m,s,s.tick),false),s.guidance);}
    public static State attach(GroundEphemeris.Model m,State s,int id){if(!s.space)throw new IllegalArgumentException("Already local");var f=m.at(id,s.tick);var p=f.local(s.position);var pose=GroundOrbit.locate(p);var q=GroundOrbit.frame(pose).rotation().conjugate().mul(f.rotation().conjugate()).mul(s.orientation()).normalize();var body=new GroundMotion.State(pose,0,false,true,false,false,q);return guidance(local(s.tick,id,body,f.localVelocity(s.position,s.velocity)),s.guidance);}
    /** Local chart is a render/vanilla proxy only when space=true. Never feeds space simulation. */
    public static GroundMotion.State view(GroundEphemeris.Model m,State s,double t){if(!s.space)return s.local;var f=m.at(s.planet,t);var pose=GroundOrbit.locate(f.local(s.position));var q=GroundOrbit.frame(pose).rotation().conjugate().mul(f.rotation().conjugate()).mul(s.orientation()).normalize();return new GroundMotion.State(pose,0,false,true,false,false,q);}
    public static Quaterniond inputOrientation(GroundEphemeris.Model m,int planet,GroundMotion.State view,Quaterniond chartOrientation,double tick){return m.at(planet,tick).rotation().mul(GroundOrbit.frame(view.pose()).rotation()).mul(chartOrientation).normalize();}
    public static int select(GroundEphemeris.Model m,Point p,int current,double t){if(m.sun().enabled())return 0;int other=1-current;return p.sub(m.at(other,t).center()).length()+GroundCosmos.HYSTERESIS<p.sub(m.at(current,t).center()).length()?other:current;}
    public static double height(GroundEphemeris.Model m,Point p,double t){return (m.sun().enabled()?p.sub(m.at(0,t).center()).length():Math.min(p.sub(m.at(0,t).center()).length(),p.sub(m.at(1,t).center()).length()))-GroundOrbit.RADIUS;}
    public static boolean clear(GroundEphemeris.Model m,GroundWorld[] w,Point p,double t){
        for(int id=0;id<m.count();id++){var local=m.at(id,t).local(p);double r=local.length();if(r<GroundOrbit.RADIUS+GroundSpace.MIN+1)return false;if(r-GroundOrbit.RADIUS-.901>=Math.max(GroundSpace.MAX,w[id].config().height()))continue;if(r>GroundOrbit.RADIUS+GroundOrbit.LIMIT)return false;if(!GroundFlight.clear(w[id],GroundOrbit.locate(local)))return false;}return true;
    }
    private static int collisionSteps(GroundEphemeris.Model m,Point v){return Math.max(1,(int)Math.ceil((v.length()+4*Math.PI*m.radius()/m.period()+Math.max(m.a().angular().length(),m.b().angular().length())*(GroundOrbit.RADIUS+GroundOrbit.LIMIT))/.2));}
    public static State resume(GroundEphemeris.Model m,GroundWorld[] worlds,State saved,long tick){
        if(m.sun().enabled()&&saved.planet()!=0)throw new IllegalArgumentException("Single-planet release requires a new world");
        if(saved.tick()>tick)throw new IllegalArgumentException("Navigation epoch is newer than universe backup");
        var s=new State(tick,saved.space,saved.planet,saved.position,saved.velocity,saved.orientation,saved.local,saved.braking,saved.guidance);
        if(s.space){if(s.position.sub(m.center()).length()>SPACE_RADIUS||!clear(m,worlds,s.position,tick))throw new IllegalStateException("Saved vessel now overlaps moving terrain");}
        else if(!GroundFlight.clear(worlds[s.planet],s.local.pose()))throw new IllegalStateException("Saved local position occupied");
        return s;
    }
    private static Point approach(Point current,Point desired){var d=desired.sub(current);return current.add(d.scale(Math.min(1,ACCEL/Math.max(1e-12,d.length()))));}
    private static Point command(Quaterniond q,PlanetMotion.Input in){var d=PlanetMotion.direction(q,0,0,1).scale(in.forward()).add(PlanetMotion.direction(q,1,0,0).scale(in.left())).add(PlanetMotion.direction(q,0,1,0).scale(in.rise()));return d.scale(1/Math.max(1,d.length()));}
    private static PlanetMotion.Input input(PlanetMotion.Input in,Quaterniond q){return new PlanetMotion.Input(in.sequence(),q.x,q.y,q.z,q.w,in.forward(),in.left(),in.rise(),in.direct(),in.fast());}
    public static State step(GroundEphemeris.Model m,GroundWorld[] w,State old,PlanetMotion.Input in,boolean toggle){
        long tick=old.tick+1;GroundEphemeris.time(tick);
        if(m.sun().enabled()){if(old.planet()!=0)throw new IllegalArgumentException("Inactive planet");if(old.guidance.target()!=0)old=guidance(old,new GroundGuidance.Options(0,old.guidance.relativeBrake(),old.guidance.landing()));}
        if(toggle||Math.abs(in.forward())+Math.abs(in.left())+Math.abs(in.rise())>1e-6)old=guidance(old,old.guidance.manual());
        if(!old.space){
            int id=old.planet;var f=m.at(id,tick);var planetQ=f.rotation().conjugate().mul(in.orientation()).normalize();var frame=GroundOrbit.frame(old.local.pose());var chartQ=frame.rotation().conjugate().mul(planetQ).normalize();
            if(old.local.pose().point().y()<=GroundCosmos.FREE){var localInput=input(in,chartQ);if(old.guidance.landing())localInput=GroundGuidance.limitInput(w[id],old.local,localInput,toggle);var next=GroundFlight.step(w[id],old.local,localInput,toggle,GroundCameraAim.universe(old));return guidance(local(tick,id,next,GroundOrbit.position(next.pose()).sub(old.position)),old.guidance);}
            var desired=command(planetQ,in).scale(UniverseMotion.speed(old.local.pose().point().y(),in.fast()));
            if(old.guidance.relativeBrake()){var now=m.at(id,old.tick);var point=now.world(old.position);desired=now.localVelocity(point,GroundGuidance.frameVelocity(m,old.guidance.target(),point,old.tick));}
            if(old.guidance.landing())desired=GroundGuidance.limitVelocity(desired,old.position.scale(1/old.position.length()),GroundGuidance.clearance(w[id],old.local.pose()));
            var v=approach(old.velocity,desired);var p=old.position;
            int steps=collisionSteps(m,v);var part=v.scale(1.0/steps);
            for(int i=0;i<steps;i++){var next=p.add(part);if(next.length()<GroundOrbit.RADIUS+GroundSpace.MIN+1||next.length()>GroundOrbit.RADIUS+GroundOrbit.LIMIT||!clear(m,w,m.at(id,old.tick+(i+1.0)/steps).world(next),old.tick+(i+1.0)/steps)){v=GroundEphemeris.ZERO;break;}p=next;}
            if(!clear(m,w,f.world(p),tick))throw new IllegalStateException("Moving collision unresolved; stopping safely");
            // Gravity owns position/velocity assistance, never the high-altitude mouse ray
            // or its turning axes. Only express the same input aim in the new chart.
            var pose=GroundOrbit.locate(p);var q=GroundOrbit.frame(pose).rotation().conjugate().mul(planetQ).normalize();
            var result=guidance(local(tick,id,new GroundMotion.State(pose,0,false,true,in.rise()>0,false,q),v),old.guidance);return pose.point().y()>EXIT?detach(m,result):result;
        }
        var q=in.orientation();var direction=command(q,in);boolean thrust=direction.length()>1e-6;boolean brake=thrust?false:toggle?!old.braking:old.braking;
        var desired=thrust?direction.scale(UniverseMotion.speed(height(m,old.position,old.tick),in.fast())):brake?GroundEphemeris.ZERO:old.guidance.relativeBrake()?GroundGuidance.frameVelocity(m,old.guidance.target(),old.position,old.tick):old.velocity;
        if(old.guidance.landing())desired=GroundGuidance.limitWorld(m,w,select(m,old.position,old.planet,old.tick),old.position,desired,old.tick);
        var v=approach(old.velocity,desired);
        var p=old.position;int steps=collisionSteps(m,v);var part=v.scale(1.0/steps);
        for(int i=0;i<steps;i++){var next=p.add(part);double t=old.tick+(i+1.0)/steps;if(next.sub(m.center()).length()>SPACE_RADIUS||!clear(m,w,next,t)){v=GroundEphemeris.ZERO;break;}p=next;}
        if(!clear(m,w,p,tick))throw new IllegalStateException("Moving collision unresolved; stopping safely");
        int id=select(m,p,old.planet,tick);var result=guidance(space(tick,id,p,v,q,brake),old.guidance);
        return p.sub(m.at(id,tick).center()).length()-GroundOrbit.RADIUS<ENTER?attach(m,result,id):result;
    }
    private GroundTransit(){}
}

