    private static void vector(String name,Point p){shader.getUniform(name).set((float)p.x(),(float)p.y(),(float)p.z());}
    public static void draw(WorldRenderContext context){
        if(!GroundClient.solar()||shader==null)return;if(mesh==null)build();if(mesh==null)return;
        var sun=GroundClient.ephemeris().sun();var home=GroundClient.planetFrame(0);var frame=GroundOrbit.frame(GroundClient.state().pose());var eye=GroundClient.universeEye();var delta=home.inverseVector(sun.position().sub(eye));double distance=Math.max(1e-6,delta.length());double blend=GroundOrbit.weight(GroundClient.eye().y());double drawDistance=Math.min(256,Math.max(16,GroundClient.view()*.5))*(1-blend)+distance*blend;double scale=drawDistance/distance;
        var centre=GroundClient.eye().add(frame.local(delta).scale(scale));var previous=RenderSystem.getShader();var color=RenderSystem.getShaderColor().clone();boolean depth=GL11.glIsEnabled(GL11.GL_DEPTH_TEST),mask=GL11.glGetBoolean(GL11.GL_DEPTH_WRITEMASK),cull=GL11.glIsEnabled(GL11.GL_CULL_FACE),enabledBlend=GL11.glIsEnabled(GL11.GL_BLEND);
        int sr=GL11.glGetInteger(GL14.GL_BLEND_SRC_RGB),dr=GL11.glGetInteger(GL14.GL_BLEND_DST_RGB),sa=GL11.glGetInteger(GL14.GL_BLEND_SRC_ALPHA),da=GL11.glGetInteger(GL14.GL_BLEND_DST_ALPHA);
